"""ORD_LINE renumbering migration."""

from decimal import Decimal


def _numeric_line_no(value: object) -> Decimal:
    """Coerce a legacy LINE_NO value for numeric ordering."""
    if value == "" or (isinstance(value, str) and not value.strip()):
        return Decimal(0)
    return Decimal(value)


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted rows and renumber surviving lines per order."""
    surviving = [
        (
            str(row.get("ORD_ID", "")),
            _numeric_line_no(row.get("LINE_NO", "")),
            position,
            row,
        )
        for position, row in enumerate(lines)
        if row.get("DEL_FLG", "") != "Y"
    ]
    surviving.sort(key=lambda item: (item[0], item[1], item[2]))

    result: list[dict] = []
    current_order: str | None = None
    new_line_no = 0

    for order_id, _, _, source_row in surviving:
        if order_id != current_order:
            current_order = order_id
            new_line_no = 1
        else:
            new_line_no += 1

        output_row = dict(source_row)
        output_row["LINE_NO"] = new_line_no
        result.append(output_row)

    return result
